-- PostgreSQL: HyperLogLog extension
CREATE EXTENSION IF NOT EXISTS hll;

-- Create HLL sketch
SELECT hll_add_agg(hll_empty(), user_id) FROM events;

-- Distinct count from sketch
hll_cardinality(hll_add_agg(hll_empty(), user_id));

-- Merge sketches (parallel/distributed)
hll_union(hll_sketch1, hll_sketch2);

-- TDigest for approximate percentiles
SELECT tdigest_agg(value) FROM measurements;

-- Query percentiles from sketch
SELECT percentile(t, 0.5) FROM (SELECT tdigest_agg(value) AS t FROM measurements) s;

-- Merge sketches (distributed)
tdigest_union(sketch1, sketch2);

-- H3 cell from lat/lng (resolution 0-15)
SELECT h3_lat_lng_to_cell(37.7749, -122.4194, 8) AS h3_cell;
-- Returns: '8828308287fffff'

-- Cell to boundary (polygon)
SELECT h3_cell_to_boundary_wkt('8828308287fffff');

-- Parent/children
SELECT h3_cell_to_parent('8828308287fffff', 6);  -- parent at res 6
SELECT h3_cell_to_children('8828308287fffff', 10); -- children at res 10

-- Compact (merge cells)
SELECT h3_compact_cells(ARRAY['8828308287fffff', '882830828bfffff']);
